import {writeFileSync} from 'node:fs';
import {CapabilityRegistry} from '../../../core/dist/index.js';
import {SqliteAgentTriggers,registerAgentManualStart} from '../../dist/index.js';
const [path,barrier,phase]=process.argv.slice(2),scope={tenantId:'tenant',agentId:'agent'},manifest={manifestVersion:1,...scope,name:'Agent',owner:{kind:'organization',id:'org'},administrators:['admin'],servicePrincipalId:'service',model:{provider:'local',model:'model'},allowedCapabilities:[],lifecycle:{enabled:true,maxAttempts:2,runTimeoutMs:1000},quotas:{maxConcurrentRuns:1,maxTokensPerRun:100,maxRunsPerDay:10}};
const hold=()=>{writeFileSync(barrier,phase);Atomics.wait(new Int32Array(new SharedArrayBuffer(4)),0,0);};
try{const triggers=new SqliteAgentTriggers(path),registry=new CapabilityRegistry(()=>{});if(phase==='during'){triggers.db.function('test_manual_crash',()=>{hold();return 0;});triggers.db.exec('CREATE TRIGGER test_manual_start_crash BEFORE INSERT ON agent_trigger_receipts BEGIN SELECT test_manual_crash(); END');}else{const enqueue=triggers.enqueue.bind(triggers);triggers.enqueue=(...args)=>{const result=enqueue(...args);hold();return result;};}registerAgentManualStart(registry,{triggers,scope,sourceId:'manual',operationId:'start',path:'/start',maxPendingRuns:2,clock:()=>100,getDefinition:()=>({version:1,manifest}),authorize:()=>true});await registry.invoke('start',{requestId:'request-1',definitionVersion:1},{...scope,principalId:'operator',origin:'ui'});throw Error('Expected process termination');}catch(error){process.send?.({error:String(error)});process.exitCode=1;}
